-- 035: page order and common cohort indexes (CW-20261001-0570).
-- EXPLAIN evidence: docs/list-index-plans.md. No rows are rewritten.
-- Descending sorts still tie-break on id ASC, so reversing an ASC index
-- cannot serve both directions. Keep expression keys identical to the store.
-- SQLite timestamp expressions preserve legacy spellings and nanoseconds.

CREATE INDEX IF NOT EXISTS idx_tasks_page_priority_asc ON tasks (priority ASC, id ASC);
CREATE INDEX IF NOT EXISTS idx_tasks_page_priority_desc ON tasks (priority DESC, id ASC);
CREATE INDEX IF NOT EXISTS idx_tasks_page_status_asc ON tasks (status ASC, id ASC);
CREATE INDEX IF NOT EXISTS idx_tasks_page_status_desc ON tasks (status DESC, id ASC);
CREATE INDEX IF NOT EXISTS idx_tasks_page_updated_at_asc ON tasks ((replace(substr(replace(replace(updated_at, ' +0000 UTC', ''), 'Z', ''), 1, 19), 'T', ' ') || '.' || CASE WHEN substr(replace(replace(updated_at, ' +0000 UTC', ''), 'Z', ''), 20, 1) = '.' THEN substr(substr(replace(replace(updated_at, ' +0000 UTC', ''), 'Z', ''), 21) || '000000000', 1, 9) ELSE '000000000' END) ASC, id ASC);
CREATE INDEX IF NOT EXISTS idx_tasks_page_updated_at_desc ON tasks ((replace(substr(replace(replace(updated_at, ' +0000 UTC', ''), 'Z', ''), 1, 19), 'T', ' ') || '.' || CASE WHEN substr(replace(replace(updated_at, ' +0000 UTC', ''), 'Z', ''), 20, 1) = '.' THEN substr(substr(replace(replace(updated_at, ' +0000 UTC', ''), 'Z', ''), 21) || '000000000', 1, 9) ELSE '000000000' END) DESC, id ASC);
