CREATE INDEX IF NOT EXISTS idx_runs_page_status_desc ON runs (status DESC, id ASC);
CREATE INDEX IF NOT EXISTS idx_runs_page_duration_asc ON runs (COALESCE(CAST(ROUND((julianday((replace(substr(replace(replace(ended_at, ' +0000 UTC', ''), 'Z', ''), 1, 19), 'T', ' ') || '.' || CASE WHEN substr(replace(replace(ended_at, ' +0000 UTC', ''), 'Z', ''), 20, 1) = '.' THEN substr(substr(replace(replace(ended_at, ' +0000 UTC', ''), 'Z', ''), 21) || '000000000', 1, 9) ELSE '000000000' END))-julianday((replace(substr(replace(replace(started_at, ' +0000 UTC', ''), 'Z', ''), 1, 19), 'T', ' ') || '.' || CASE WHEN substr(replace(replace(started_at, ' +0000 UTC', ''), 'Z', ''), 20, 1) = '.' THEN substr(substr(replace(replace(started_at, ' +0000 UTC', ''), 'Z', ''), 21) || '000000000', 1, 9) ELSE '000000000' END)))*86400000) AS INTEGER), -1) ASC, id ASC);
CREATE INDEX IF NOT EXISTS idx_runs_page_duration_desc ON runs (COALESCE(CAST(ROUND((julianday((replace(substr(replace(replace(ended_at, ' +0000 UTC', ''), 'Z', ''), 1, 19), 'T', ' ') || '.' || CASE WHEN substr(replace(replace(ended_at, ' +0000 UTC', ''), 'Z', ''), 20, 1) = '.' THEN substr(substr(replace(replace(ended_at, ' +0000 UTC', ''), 'Z', ''), 21) || '000000000', 1, 9) ELSE '000000000' END))-julianday((replace(substr(replace(replace(started_at, ' +0000 UTC', ''), 'Z', ''), 1, 19), 'T', ' ') || '.' || CASE WHEN substr(replace(replace(started_at, ' +0000 UTC', ''), 'Z', ''), 20, 1) = '.' THEN substr(substr(replace(replace(started_at, ' +0000 UTC', ''), 'Z', ''), 21) || '000000000', 1, 9) ELSE '000000000' END)))*86400000) AS INTEGER), -1) DESC, id ASC);
